package expo.modules.placementguard
import android.content.Context
import android.security.keystore.KeyGenParameterSpec
import android.security.keystore.KeyProperties
import android.util.Base64
import java.security.KeyStore
import javax.crypto.Cipher
import javax.crypto.KeyGenerator
import javax.crypto.SecretKey
import javax.crypto.spec.GCMParameterSpec

class SettingsStore(context:Context){
 private val p=context.getSharedPreferences("placement_guard",Context.MODE_PRIVATE)
 init { synchronized(lock) { if(!p.getBoolean("schemaV1",false)){val migration=p.edit().putBoolean("enabled",false).putBoolean("dryRun",true).putBoolean("schemaV1",true); if(p.contains("apiKey")){migration.putString("apiKeyEncrypted",encrypt(p.getString("apiKey","").orEmpty())).remove("apiKey")}; check(migration.commit()){ "Settings could not be migrated" } } }
 private fun key():SecretKey{val ks=KeyStore.getInstance("AndroidKeyStore").apply{load(null)};val alias="placementguard_api_v1";return (ks.getKey(alias,null) as? SecretKey)?:KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore").apply{init(KeyGenParameterSpec.Builder(alias,KeyProperties.PURPOSE_ENCRYPT or KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build())}.generateKey()}
 private fun encrypt(v:String):String{if(v.isEmpty())return "";val c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key());return Base64.encodeToString(c.iv+c.doFinal(v.toByteArray(Charsets.UTF_8)),Base64.NO_WRAP)}
 private fun decrypt(v:String):String{if(v.isEmpty())return "";try{val b=Base64.decode(v,Base64.NO_WRAP);require(b.size>12);val c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key(),GCMParameterSpec(128,b.copyOfRange(0,12)));return String(c.doFinal(b.copyOfRange(12,b.size)),Charsets.UTF_8)}catch(_:Exception){throw IllegalStateException("Storage unavailable. Unable to decrypt API key; settings have not been reset.")}}
 val apiKey:String get(){val encrypted=p.getString("apiKeyEncrypted",null);return if(encrypted!=null)decrypt(encrypted) else p.getString("apiKey","").orEmpty()}
 val enabled:Boolean get()=p.getBoolean("enabled",false)
 val dryRun:Boolean get()=p.getBoolean("dryRun",true)
 val ignoreGroups:Boolean get()=p.getBoolean("ignoreGroups",true)
 val threshold:Float get()=p.getFloat("threshold",.85f)
 val cooldownHours:Int get()=p.getInt("cooldown",24)
 val model:String get()=p.getString("model",AppConfig.MODEL).orEmpty()
 val replyText:String get()=p.getString("reply",AppConfig.DEFAULT_REPLY).orEmpty()
 val exclusionsRaw:String get()=p.getString("exclusions","").orEmpty()
 fun snapshot():Map<String,Any> = mapOf("apiKey" to apiKey,"enabled" to enabled,"dryRun" to dryRun,"ignoreGroups" to ignoreGroups,"threshold" to threshold,"cooldownHours" to cooldownHours,"model" to model,"replyText" to replyText,"exclusionsRaw" to exclusionsRaw)
 fun save(v:Map<String,Any?>){synchronized(lock){val e=p.edit();(v["apiKey"] as? String)?.let{e.putString("apiKeyEncrypted",encrypt(it.filterNot{c->c.isWhitespace()}.trim('"','\''))).remove("apiKey")};(v["enabled"] as? Boolean)?.let{e.putBoolean("enabled",it)};(v["dryRun"] as? Boolean)?.let{e.putBoolean("dryRun",it)};(v["ignoreGroups"] as? Boolean)?.let{e.putBoolean("ignoreGroups",it)};(v["threshold"] as? Number)?.let{val n=it.toFloat();require(n.isFinite()&&n in .5f..1f){"Confidence must be 0.50–1.00"};e.putFloat("threshold",n)};(v["cooldownHours"] as? Number)?.let{val n=it.toDouble();require(n in 1.0..720.0&&n%1.0==0.0){"Cooldown must be 1–720 hours"};e.putInt("cooldown",n.toInt())};(v["model"] as? String)?.let{e.putString("model",it.trim())};(v["replyText"] as? String)?.let{e.putString("reply",it)};(v["exclusionsRaw"] as? String)?.let{e.putString("exclusions",it)};check(e.commit()){"Settings could not be saved. Retry."}}}
 fun excluded(sender:String)=exclusionsRaw.lines().map{it.trim()}.filter{it.isNotEmpty()}.any{it.equals(sender.trim(),ignoreCase=true)}
 companion object{private val lock=Any()}
}

package expo.modules.placementguard
import android.content.*
import android.provider.Settings
import android.service.notification.NotificationListenerService
import expo.modules.kotlin.modules.Module
import expo.modules.kotlin.modules.ModuleDefinition
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
class PlacementGuardModule:Module(){
 private val io=CoroutineScope(SupervisorJob()+Dispatchers.IO)
 private val ctx get()=requireNotNull(appContext.reactContext)
 private fun permission():Boolean{val component=ComponentName(ctx,WhatsAppNotificationListener::class.java);return Settings.Secure.getString(ctx.contentResolver,"enabled_notification_listeners").orEmpty().split(':').mapNotNull{ComponentName.unflattenFromString(it)}.contains(component)}
 override fun definition()=ModuleDefinition{
  Name("PlacementGuard")
  AsyncFunction("getSettings"){SettingsStore(ctx).snapshot()}.runOnQueue(io)
  AsyncFunction("saveSettings"){v:Map<String,Any?>->SettingsStore(ctx).save(v);true}.runOnQueue(io)
  AsyncFunction("getLogs"){ActivityLog.read(ctx)}
  AsyncFunction("clearLogs"){ActivityLog.clear(ctx);true}
  AsyncFunction("getStatus"){mapOf("permission" to permission(),"connected" to WhatsAppNotificationListener.connected)}
  AsyncFunction("openNotificationAccess"){ctx.startActivity(Intent(Settings.ACTION_NOTIFICATION_LISTENER_SETTINGS).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));NotificationListenerService.requestRebind(ComponentName(ctx,WhatsAppNotificationListener::class.java));true}
  AsyncFunction("getModels"){NimClassifier().models(SettingsStore(ctx).apiKey)}.runOnQueue(io)
  AsyncFunction("testNim"){sample:String->try{val s=SettingsStore(ctx);val r=NimClassifier().classify(s.apiKey,s.model,"Test",listOf(sample.take(2000)));ActivityLog.add(ctx,"AI connection test passed");mapOf("placementRelated" to r.placementRelated,"confidence" to r.confidence,"reason" to r.reason)}catch(e:Exception){ActivityLog.add(ctx,"AI connection test failed; check key, model and internet");throw e}}.runOnQueue(io)
 }
}

package expo.modules.placementguard
import android.app.*
import android.content.*
import android.os.*
import android.service.notification.*
import java.security.MessageDigest
import java.util.concurrent.*
class WhatsAppNotificationListener:NotificationListenerService(){
 private val pool=ThreadPoolExecutor(1,1,0L,TimeUnit.MILLISECONDS,ArrayBlockingQueue<Runnable>(12),ThreadPoolExecutor.AbortPolicy())
 private val recent=linkedMapOf<String,Pair<Long,MutableList<String>>>()
 companion object{@Volatile var connected=false}
 override fun onListenerConnected(){connected=true;ActivityLog.add(this,"Notification listener connected")}
 override fun onListenerDisconnected(){connected=false;requestRebind(ComponentName(this,WhatsAppNotificationListener::class.java))}
 override fun onDestroy(){connected=false;pool.shutdownNow();super.onDestroy()}
 private fun hash(s:String)=MessageDigest.getInstance("SHA-256").digest(s.toByteArray()).joinToString(""){"%02x".format(it)}
 override fun onNotificationPosted(sbn:StatusBarNotification){
  if(sbn.packageName!=AppConfig.WHATSAPP_PACKAGE)return
  val n=sbn.notification;if(n.flags and Notification.FLAG_GROUP_SUMMARY!=0)return
  val style=Notification.MessagingStyle.extractMessagingStyleFromNotification(n)
  if(style!=null&&style.messages.lastOrNull()?.sender==null)return
  val e=n.extras;val title=e.getCharSequence(Notification.EXTRA_TITLE)?.toString()?.trim().orEmpty()
  val text=e.getCharSequence(Notification.EXTRA_TEXT)?.toString()?.trim().orEmpty()
  if(title.isBlank()||text.isBlank())return
  val group=e.getBoolean(Notification.EXTRA_IS_GROUP_CONVERSATION,false)||e.getCharSequence(Notification.EXTRA_CONVERSATION_TITLE)!=null
  val st=SettingsStore(this);if(!st.enabled||st.excluded(title)||(st.ignoreGroups&&group))return
  if(n.actions?.none{a->a.remoteInputs?.any{it.allowFreeFormInput}==true}!=false)return
  val now=System.currentTimeMillis();if(now-sbn.postTime>120000)return
  val id=hash(sbn.key+"|"+title)
  val cd=CooldownStore(this);if(!cd.canReply(id,st.cooldownHours))return
  val dedup=getSharedPreferences("pg_seen",MODE_PRIVATE);val sig=hash(id+"|"+text)
  if(now-dedup.getLong(sig,0)<120000)return
  val edit=dedup.edit();dedup.all.filter{(_,v)->v is Long&&now-v>120000}.keys.forEach{edit.remove(it)};edit.putLong(sig,now).apply()
  val history=synchronized(recent){recent.entries.removeAll{now-it.value.first>30*60000};if(recent.size>=100)recent.remove(recent.keys.first());val list=recent.getOrPut(id){now to mutableListOf()}.second;if(list.lastOrNull()!=text)list.add(text.take(2000));while(list.size>6)list.removeAt(0);recent[id]=now to list;list.toList()}
  try{pool.execute{try{
   val usedKey=st.apiKey;val usedModel=st.model
   if(!st.enabled)return@execute
   val r=NimClassifier().classify(usedKey,usedModel,title,history)
   ActivityLog.add(this,"Classified: ${if(r.placementRelated)"placement" else "personal/unclear"} (${(r.confidence*100).toInt()}%)")
   val latest=SettingsStore(this)
   if(!latest.enabled||latest.excluded(title)||(latest.ignoreGroups&&group)||latest.model!=usedModel||latest.apiKey!=usedKey||!r.placementRelated||r.confidence<latest.threshold||!cd.canReply(id,latest.cooldownHours))return@execute
   if(latest.dryRun){ActivityLog.add(this,"TEST: qualified; no reply sent");return@execute}
   if(System.currentTimeMillis()-now>90000){ActivityLog.add(this,"Skipped stale notification");return@execute}
   if(latest.replyText.isBlank()||latest.replyText.length>2000)return@execute
   if(sendReply(n,latest.replyText)){cd.mark(id);ActivityLog.add(this,"Automatic reply sent")}else ActivityLog.add(this,"Quick-reply action unavailable; no reply sent")
  }catch(_:Exception){ActivityLog.add(this,"Classification failed; no reply sent. Run connection test.")}}}catch(_:RejectedExecutionException){ActivityLog.add(this,"Busy: notification skipped; no reply sent")}
 }
 private fun sendReply(n:Notification,msg:String):Boolean{val action=n.actions?.firstOrNull{a->a.remoteInputs?.any{it.allowFreeFormInput}==true}?:return false;val inputs=action.remoteInputs?.filter{it.allowFreeFormInput}?.toTypedArray()?:return false;val i=Intent();val b=Bundle();inputs.forEach{b.putCharSequence(it.resultKey,msg)};RemoteInput.addResultsToIntent(inputs,i,b);return try{action.actionIntent.send(this,0,i);true}catch(_:Exception){false}}
}

