export type Settings = {apiKey:string;enabled:boolean;dryRun:boolean;ignoreGroups:boolean;threshold:number;cooldownHours:number;model:string;replyText:string;exclusionsRaw:string};
export const defaults:Settings={apiKey:'',enabled:false,dryRun:true,ignoreGroups:true,threshold:.85,cooldownHours:24,model:'openai/gpt-oss-20b',replyText:'Hello! I’m currently unavailable for placement-related queries. Kindly contact another Placement Representative (PR) of your respective branch for assistance. Thank you.',exclusionsRaw:''};
export const cleanKey=(v:string)=>v.replace(/\s/g,'').replace(/^["']+|["']+$/g,'');
export function validate(s:Settings){if(s.apiKey&&!/^nvapi-[A-Za-z0-9_-]+$/.test(s.apiKey))throw Error('Paste only the NVIDIA key beginning with nvapi-.');if(!Number.isFinite(s.threshold)||s.threshold<.5||s.threshold>1)throw Error('Confidence must be between 0.50 and 1.00.');if(!Number.isInteger(s.cooldownHours)||s.cooldownHours<1||s.cooldownHours>720)throw Error('Cooldown must be 1–720 whole hours.');if(!/^[a-zA-Z0-9._-]+\/[a-zA-Z0-9._-]+$/.test(s.model))throw Error('Model must use provider/model format.');if(!s.replyText.trim()||s.replyText.length>2000)throw Error('Reply must contain 1–2000 characters.');return s;}
export function friendlyError(e:unknown){const m=String((e as any)?.message||e);const known=['API key','NVIDIA key','Confidence','Cooldown','Model must','Reply must','Settings could not','Storage unavailable','HTTP 401','HTTP 403','HTTP 404','HTTP 410','HTTP 429','timed out','No classification','Invalid classification','Network unavailable','HTTP 5'];const hit=known.find(x=>m.includes(x));if(!hit)return 'Could not complete this action. Check connectivity and try again.';if(hit==='HTTP 410'||hit==='HTTP 404')return 'This model is unavailable. Load available models and select another.';if(hit==='HTTP 401'||hit==='HTTP 403')return 'NVIDIA rejected access. Check your key and account permissions.';if(hit==='HTTP 429')return 'NVIDIA rate limit reached. Wait a minute before retrying.';if(hit==='No classification'||hit==='Invalid classification')return 'Model returned an incomplete classification. Try another model.';if(hit==='HTTP 5')return 'NVIDIA is temporarily unavailable. Try later.';return m.substring(m.indexOf(hit),m.indexOf(hit)+170).replace(/nvapi-[\w-]+/g,'[hidden]');}

