import {test} from 'node:test';
import assert from 'node:assert/strict';
import {defaults,cleanKey,validate,friendlyError} from '../src/settings.ts';
test('keys copied with formatting are cleaned without disclosing them',()=>{assert.equal(cleanKey(' "\nnvapi-EXAMPLE_only_123\r\n" '),'nvapi-EXAMPLE_only_123');assert.equal(friendlyError(Error('untrusted secret nvapi-EXAMPLE_only_123')).includes('EXAMPLE'),false);});
test('invalid numeric and reply settings cannot enable automation',()=>{for(const threshold of [NaN,Infinity,.49,1.1])assert.throws(()=>validate({...defaults,threshold}));for(const cooldownHours of [0,1.5,721])assert.throws(()=>validate({...defaults,cooldownHours}));assert.throws(()=>validate({...defaults,replyText:' '}));assert.throws(()=>validate({...defaults,model:'invalid'}));assert.throws(()=>validate({...defaults,apiKey:'Bearer BAD'}));assert.equal(validate(defaults).enabled,false);});
test('valid configuration survives serialization',()=>{const saved={...defaults,apiKey:'nvapi-EXAMPLE_only_123',cooldownHours:48,threshold:.92,model:'openai/gpt-oss-20b',exclusionsRaw:'Test Contact\n+911234567890'};assert.deepEqual(validate(JSON.parse(JSON.stringify(saved))),saved);});
test('retirement, access, incomplete response and network errors have actionable messages',()=>{assert.match(friendlyError(Error('HTTP 410')),/unavailable/);assert.match(friendlyError(Error('HTTP 401')),/rejected/);assert.match(friendlyError(Error('HTTP 429')),/rate limit/);assert.match(friendlyError(Error('No classification returned')),/incomplete/);assert.match(friendlyError(Error('Request timed out. Try again.')),/timed out/);});
